-- 622: Original BrillaPrep BECE Integrated Science sprint 3 beta questions, part 4 of 8 (batch bece-int-science-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC or NaCCA examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_622_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_622_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bece_intsci_s3_021', 'topic_bece_science_electricity', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Two lamps are connected in series in a circuit. One lamp blows (its filament breaks). What happens to the other lamp?', 'multiple_choice', NULL, '["A. It goes out because the circuit is now incomplete","B. It becomes brighter because it gets all the current","C. It keeps shining normally","D. It becomes dimmer but stays on"]', 'A', 'In a series circuit there is only one path for the current. A broken filament breaks that single path, so no current flows and the second lamp goes out. (In a parallel circuit the second lamp would stay on; a lamp cannot become brighter when the current has stopped completely.) Therefore the correct answer is A: It goes out because the circuit is now incomplete.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Predict', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_022', 'topic_bece_science_electricity', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Which instrument is used to measure the current flowing through a lamp, and how is it connected?', 'multiple_choice', NULL, '["A. A voltmeter, connected in series with the lamp","B. An ammeter, connected in series with the lamp","C. An ammeter, connected in parallel with the lamp","D. A voltmeter, connected across the battery only"]', 'B', 'Current is measured with an ammeter, and because the same current must pass through it, the ammeter is connected in series with the lamp. A voltmeter measures potential difference and is connected in parallel across a component. (An ammeter connected in parallel would create a short circuit across the lamp.) Therefore the correct answer is B: An ammeter, connected in series with the lamp.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_023', 'topic_bece_science_electricity', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Why are the lamps and sockets in a house wired in parallel rather than in series?', 'multiple_choice', NULL, '["A. Parallel wiring always uses thinner cables and less copper","B. In series the lamps would burn out immediately","C. Each appliance then receives the full mains voltage and can be switched on or off independently","D. Parallel circuits prevent any current from flowing when one lamp fails"]', 'C', 'In parallel, each branch is connected directly across the supply, so every appliance receives the full mains voltage, and a fault or switch in one branch does not affect the others. In series the voltage would be shared between the appliances and one fault would switch everything off. (Cable thickness depends on current rating, not on the circuit layout.) Therefore the correct answer is C: Each appliance then receives the full mains voltage and can be switched on or off independently.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_024', 'topic_bece_science_electricity', 'subj_bece_science', 'exam_bece', NULL, NULL, 'An electromagnet made from a coil of wire around an iron nail picks up only a few paper clips. Which change will make it stronger?', 'multiple_choice', NULL, '["A. Use a wooden core instead of the iron nail","B. Reduce the current flowing through the coil","C. Spread the turns of the coil farther apart","D. Increase the number of turns of wire on the coil"]', 'D', 'The strength of an electromagnet increases with more turns of wire, a larger current and a soft-iron core. Adding turns concentrates the magnetic field around the core. (Wood is not magnetic, reducing the current weakens the field, and spreading the turns out weakens it as well.) Therefore the correct answer is D: Increase the number of turns of wire on the coil.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_025', 'topic_bece_science_electricity', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Explain the difference between an electrical conductor and an insulator, giving one example of each.', 'short_answer', NULL, NULL, 'A conductor allows electric current to pass through it easily, for example copper wire; an insulator does not allow current to pass through it, for example rubber or plastic.', 'An electrical conductor is a material that lets charge flow through it easily because it has many free electrons — metals such as copper and aluminium are good conductors, which is why cables have a copper core. An insulator does not allow current to pass through it — rubber, plastic and dry wood are examples, which is why cables are covered with plastic.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_026', 'topic_bece_science_electricity', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A resistor of 4 Ω is connected to a battery and a current of 0.5 A flows through it. Calculate the voltage across the resistor.', 'calculation', NULL, NULL, '2 V', 'Using Ohm’s law, V = I × R = 0.5 A × 4 Ω = 2 V. Answer: the voltage across the resistor is 2 V.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
CREATE TABLE _migration_622_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS _migration_622_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_622_guard;
INSERT INTO _migration_622_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_622_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_622_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_622_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_622_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
DELETE FROM _migration_622_guard;
INSERT INTO _migration_622_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_622_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_622_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_622_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_622_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
DROP TABLE _migration_622_guard;
DROP TABLE _migration_622_expected;
DROP TABLE _migration_622_expected_parts;
